import {state,active,SAMPLE_TEXT} from './state.js';
export const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={back:'m14 6-6 6 6 6',next:'m10 6 6 6-6 6',plus:'M12 5v14M5 12h14',close:'m6 6 12 12M6 18 18 6',search:'M20 20l-5-5M17 10a7 7 0 1 1-14 0 7 7 0 0 1 14 0',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1Z',document:'M6 3h8l4 4v14H6ZM14 3v5h4M9 12h6M9 16h6',cards:'M3 7h18v13H3ZM7 3h13v4M7 11h3v4H7ZM13 11h5M13 15h5',camera:'M4 7h4l2-3h4l2 3h4v13H4ZM16 13a4 4 0 1 1-8 0 4 4 0 0 1 8 0',image:'M3 4h18v16H3ZM3 16l5-5 5 5 3-3 5 5M8 8h.01',check:'m5 12 4 4L19 6',rotate:'M4 7v5h5M4 12a8 8 0 1 1 4 7',crop:'M7 3v14h14M3 7h14v14',text:'M4 5h16M12 5v15M8 20h8',layout:'M3 3h18v18H3ZM3 9h18M12 9v12',trash:'M4 6h16M9 3h6M6 6l1 15h10l1-15M10 10v7M14 10v7',share:'M12 16V3m-4 4 4-4 4 4M5 11v10h14V11',download:'M12 3v13m-4-4 4 4 4-4M4 17v4h16v-4',scan:'M3 8V3h5M16 3h5v5M21 16v5h-5M8 21H3v-5M6 12h12',flash:'m13 2-8 12h6l-1 8 9-13h-7Z',grid:'M3 3h7v7H3ZM14 3h7v7h-7ZM3 14h7v7H3ZM14 14h7v7h-7',move:'m8 6 4-4 4 4M12 2v20m-4-4 4 4 4-4M2 12h20m-4-4 4 4-4 4M6 8l-4 4 4 4',up:'m6 14 6-6 6 6',down:'m6 10 6 6 6-6',lab:'M9 3h6M10 3v7l-5 9v2h14v-2l-5-9V3M8 15h8',folder:'M3 5h7l2 3h9v12H3Z'};
export function icon(name){return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]??paths.document}"/></svg>`}
export function ib(name,label,action){return `<button class="icon-button" aria-label="${esc(label)}" data-action="${action}">${icon(name)}</button>`}
export function btn(label,action,primary=false,ico='next',disabled=false){return `<button class="${primary?'primary':'secondary'}" data-action="${action}" ${disabled?'disabled':''}>${ico?icon(ico):''}<span>${label}</span></button>`}
export function header(title,subtitle='',right='',back=true){return `<header class="app-header">${back?ib('back','Back','back'):'<img class="app-mark" src="assets/logo.png" alt="">'}<div class="header-title"><h1>${title}</h1>${subtitle?`<p>${subtitle}</p>`:''}</div>${right}</header>`}
export function footer(content){return `<footer class="app-footer">${content}</footer>`}
export function status(){return `<div class="statusbar"><span>9:41</span><span class="system-icons" aria-label="Network and battery"><svg viewBox="0 0 42 16" aria-hidden="true"><path d="M1 13h3V9H1zm5 0h3V6H6zm5 0h3V3h-3z" fill="currentColor"/><path d="M18 5q6-6 12 0m-9 3q3-3 6 0m-4 3h2" fill="none" stroke="currentColor" stroke-width="1.6"/><rect x="34" y="3" width="6" height="10" rx="1" fill="currentColor"/></svg></span></div>`}
export function choice(label,detail,value,field,current,ico='document'){return `<button class="choice ${current===value?'selected':''}" data-action="choose:${field}:${value}" aria-pressed="${current===value}"><span class="choice-icon">${icon(ico)}</span><span><strong>${label}</strong><small>${detail}</small></span><span class="radio">${current===value?icon('check'):''}</span></button>`}
export function segments(values,current,field){return `<div class="segments" role="group" aria-label="${esc(field)}">${values.map(v=>`<button data-action="choose:${field}:${esc(v)}" aria-pressed="${current===v}">${esc(field==='workflow'?(v==='paired'?'Front & back':'Multiple cards'):v)}</button>`).join('')}</div>`}
export function imageStyle(item){const filter=item?.filter??'Color';const original=filter==='Original';return `grayscale(${['Grayscale','B&W'].includes(filter)?1:0}) brightness(${original?100:item?.brightness??100}%) contrast(${original?100:(item?.contrast??100)*(filter==='B&W'?2:1)}%)`}
export function paper(options={}){const item=options.item??active();const card=item?.kind==='card';const filter=item?.filter??'Color';const angle=item?.rotation??0;if(item?.image)return `<div class="paper source-image ${card?'id-paper':''} ${options.small?'small-paper':''}" style="--rotation:${angle}deg;filter:${imageStyle(item)}"><img src="${esc(item.image)}" alt="Imported image"></div>`;return `<div class="paper ${card?'id-paper':''} ${options.small?'small-paper':''} filter-${filter.toLowerCase()}" style="--rotation:${angle}deg;filter:${imageStyle(item)}" aria-label="Fictional ${card?'card':'document'} sample">${card?`<div class="id-top">STUDIO / MEMBERSHIP <span>DEMO</span></div><div class="id-body">${item?.side==='Back'?'<div class="card-back-pattern"></div>':'<div class="portrait-placeholder">'+icon('cards')+'</div>'}<div><b>${item?.side==='Back'?'Membership information':'Sample member'}</b><p>Paper Study Studio</p><small>${esc(item?.side??'Front')} · Design sample</small></div></div><div class="id-bottom">NOT AN IDENTITY DOCUMENT</div>`:`<div class="paper-kicker">PAPER STUDY / 2026</div><h2>Project notes</h2><div class="paper-rule"></div><p>A clearer archive</p><div class="paper-lines">${'<i></i>'.repeat(5)}</div><div class="paper-columns"><div><small>PROJECT</small><p>Paper Study</p></div><div><small>DATE</small><p>14 October 2026</p></div></div><div class="paper-lines">${'<i></i>'.repeat(8)}</div><div class="paper-note">Keep the original. Make the words useful.</div>`}</div>`}
export function thumb(item,i){return `<button class="thumb ${state.active===i?'active':''}" data-action="active:${i}" aria-label="Select ${esc(item.label)}">${paper({item,small:true})}<span>${i+1}</span></button>`}
export function empty(title,body,action=''){return `<div class="empty-state">${icon('folder')}<h2>${title}</h2><p>${body}</p>${action}</div>`}
export function titleBlock(title,body){return `<div class="title-block"><h2>${title}</h2>${body?`<p>${body}</p>`:''}</div>`}
export function layoutPages(){
 if(state.mode!=='cards')return state.captures.map(r=>[r]);
 const capacity=state.template==='Grid'?4:2,used=new Set(),units=[];
 for(const r of state.captures){
  if(used.has(r.id))continue;
  const key=r.pairLabel?.trim();
  const pair=key&&r.side!=='Single'?state.captures.filter(p=>p.side!=='Single'&&p.pairLabel?.trim()===key):[];
  const valid=pair.length===2&&pair.some(p=>p.side==='Front')&&pair.some(p=>p.side==='Back');
  const unit=valid?[pair.find(p=>p.side==='Front'),pair.find(p=>p.side==='Back')]:[r];
  unit.forEach(p=>used.add(p.id));units.push(unit);
 }
 const pages=[];let sheet=[];
 for(const unit of units){if(sheet.length+unit.length>capacity){pages.push(sheet);sheet=[];}sheet.push(...unit);if(sheet.length===capacity){pages.push(sheet);sheet=[];}}
 if(sheet.length)pages.push(sheet);return pages;
}
export function layoutSheet(pageIndex=0){const cards=state.mode==='cards';const cols=cards&&state.template!=='Stacked'?2:1;const pages=layoutPages();const total=pages.length;return `<div class="layout-paper ${state.paper==='Letter'?'letter':''}" style="--cols:${cols};--sheet-padding:${state.margins==='Compact'?'12px':'24px'}"><div class="layout-grid">${(pages[pageIndex]??[]).map(item=>paper({item,small:true})).join('')}</div></div><p class="caption">${total} ${total===1?'sheet':'sheets'}${total>1?` · sheet ${pageIndex+1} of ${total}`:''} · ${esc(state.paper)} · aspect ratio preserved</p>`}
export function sampleText(){return state.captures.map(r=>r.text||SAMPLE_TEXT).join('\n\n')}
